import { useState } from 'react';

import QUESTIONS from '../question.jsx'; 

export default function Quiz() {
    // 初始化userAnswers 为 []
    const [userAnswers, setUserAnswers] = useState([]); 

    const activeQuestionIndex = userAnswers.length; 
    const shuffledAnswers = [...QUESTIONS[activeQuestionIndex].answers];

    shuffledAnswers.sort(() => Math.random() - 0.5); 
    const quizIsComplete = activeQuestionIndex === QUESTIONS.length;

    /*
        这里定义了一个名为 handleSelectAnswer 的函数，这个函数接收一个参数 selectedAnswer。
        这个参数代表用户选中的答案，可能是在一个问卷、测验或其他任何需要用户选择答案的场景中。
    */

    /*
        setUserAnswers 调用时接收一个函数作为参数，
        这个函数又接收当前状态 prevUserAnswers 作为其参数，
        并返回一个新的状态值。

        prevUserAnswers 是用户之前的答案数组的当前状态。

        return [...prevUserAnswers, selectedAnswer] 通过展开运算符 (...) 创建了一个新数组，
        这个新数组包含了之前所有的答案（prevUserAnswers 中的内容），
        并在数组的末尾添加了新选中的答案 selectedAnswer。
    */
   
    function handleSelectAnswer(selectedAnswer) {
        setUserAnswers((prevUserAnswers) => {
            return [...prevUserAnswers, selectedAnswer]
        }); 
    }

    if (quizIsComplete) {
        return <div id = "summary">
            <img />
            <h2>Quiz Completed!</h2>
        </div>
    }

    return (
        <div id = "quiz">
            <h2>{QUESTIONS[activeQuestionIndex].text}</h2>
            <ul id = "answers">
                {shuffledAnswers.map((answer) => (
                    <li key = {answer} className = "answer">
                        <button onClick = {() => handleSelectAnswer(answer)}>{answer}</button>
                    </li>
                ))}
            </ul>
        </div>
    );
}
